<?php
require_once __DIR__ . '/layout.php';
$users=load_data('users'); $requests=requests_all(); $rows=request_rows(); $month=date('Y-m');
$totalUsers=count($users); $totalRequests=count($requests); $monthRequests=count(array_filter($requests, fn($r)=>month_of($r['requested_at']??'')===$month)); $openRequests=count(array_filter($requests, fn($r)=>in_array($r['status']??'', ['new','progress']))); $latest=array_slice($rows,0,8);
page_header('Dashboard','dashboard'); ?>
<div class="grid"><div class="card"><div class="muted">Users</div><div class="stat"><?= $totalUsers ?></div></div><div class="card"><div class="muted">Total requests</div><div class="stat"><?= $totalRequests ?></div></div><div class="card"><div class="muted">Requests this month</div><div class="stat"><?= $monthRequests ?></div></div><div class="card"><div class="muted">New / in progress</div><div class="stat"><?= $openRequests ?></div></div></div>
<div class="card"><h2>Quick actions</h2><a class="btn" href="request_form.php">Add request</a> <a class="btn secondary" href="user_form.php">Add user</a> <a class="btn secondary" href="stats.php">View statistics</a></div>
<div class="card"><h2>Recent requests</h2><table><thead><tr><th>Date/time</th><th>User</th><th>Office</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($latest as $row): ?><tr><td><?= h(fmt_dt($row['requested_at'])) ?></td><td><?= h($row['full_name']) ?></td><td><?= h($row['office']) ?></td><td><?= h($row['reason']) ?></td><td><span class="badge <?= h($row['status']==='done'?'done':($row['status']==='progress'?'progress':'new')) ?>"><?= h($row['status']) ?></span></td><td><a class="btn small" href="request_form.php?id=<?= (int)$row['id'] ?>">Open</a></td></tr><?php endforeach; ?><?php if(!$latest): ?><tr><td colspan="6">There are no requests yet.</td></tr><?php endif; ?></tbody></table></div><?php page_footer(); ?>
